using UnityEngine;using TMPro;public class Enemy : MonoBehaviour{    [SerializeField] private string unitName;    [SerializeField] private int health;    [SerializeField] private int level;    [Header("—сылки на UI")]    [SerializeField] private TextMeshProUGUI nameText;    [SerializeField] private TextMeshProUGUI healthText;    [SerializeField] private TextMeshProUGUI levelText;    public string UnitName => unitName;    public int Health => health;    public int Level => level;    private void Start()    {        UpdateUI();    }    public void MakeBoss()    {        unitName = "Boss";        health *= 3;        level += 1;        UpdateUI();    }    private void UpdateUI()    {        if (nameText != null) nameText.text = ":" + unitName;        if (healthText != null) healthText.text = "”рон: " + health;        if (levelText != null) levelText.text = "”ровень: " + level;    }}